import pandas as pd

def clean(df):
    df = df.copy()
    if 'Category' in df.columns:
        df['Category'] = df['Category'].astype(str).str.strip()
    if 'Region' in df.columns:
        df['Region'] = df['Region'].replace({'Suoth': 'South', 'Nort': 'North'})
    return df

def answer(df):
    df_elec = df[df['Category'] == 'Electronics'].copy()
    df_elec = df_elec.dropna(subset=['Region'])
    result = df_elec.groupby('Region')['Revenue'].sum().to_dict()
    return result
